fn serialize(v: &Vec[Int]) -> Str {
  var s = "[";
  for i in 0..v.len() {
    if i > 0 { s = s + ","; }
    s = s + v[i].to_str();
  }
  s = s + "]";
  return s;
}

fn deserialize(s: Str) -> Option[Vec[Int]] {
  if s.len() < 2 || s[0] != '[' { return None(); }
  var result = Vec[Int]();
  // Simplified parser
  let inner = s[1..s.len()-1];
  return Some(result);
}

fn prop_roundtrip(v: &Vec[Int]) -> Bool {
  let s = serialize(v);
  match deserialize(s) {
    Some(restored) => return restored == v,
    None => return false,
  }
}

fn main() -> Int {
  let test = Vec[Int]();
  test.push(1); test.push(2); test.push(3);
  if prop_roundtrip(&test) { return 1; }
  return 0;
}
